    sense = best > 0 ? 1 : -1;
    const comp = [0, 1, 2].find((i) => Math.abs(axis[i]) > 1e-9), lam = frac01((sense * g[comp]) / axis[comp]);
    const m = Math.round(lam * n * 12) / 12;
